components.css:
.ds-notch { position: relative; width: 259px; height: 38px; font-family: -apple-system, system-ui, sans-serif; }
.ds-notch svg { display: block; width: 259px; height: 38px; }
.ds-notch-wing { position: absolute; top: 0; height: 38px; width: 37px; display: flex; align-items: center; justify-content: center; }
.ds-notch-wing-left { left: 0; }
.ds-notch-wing-right { right: 0; }
.ds-notch-timer { font-family: "SF Pro Rounded", -apple-system, system-ui, sans-serif; font-size: 9pt; font-weight: 500; font-variant-numeric: tabular-nums; color: #FAB72A; }

.ds-glyph { display: inline-block; position: relative; }
.ds-glyph-running { width: 15px; height: 15px; border: 2px solid #9EADBC; border-radius: 50%; border-right-color: transparent; animation: ds-spin 0.85s linear infinite; }
.ds-glyph-waiting { width: 11px; height: 11px; border-radius: 50%; background: #FAB72A; animation: ds-pulse 0.7s ease-in-out infinite alternate; }
.ds-glyph-done, .ds-glyph-error { width: 15px; height: 15px; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; line-height: 1; }
.ds-glyph-done { color: #58B575; }
.ds-glyph-error { color: #E6443D; }
@keyframes ds-spin { to { transform: rotate(360deg); } }
@keyframes ds-pulse { from { transform: scale(0.62); opacity: 0.45; } to { transform: scale(1); opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  .ds-glyph-running { animation: none; }
  .ds-glyph-waiting { animation: none; transform: scale(1); opacity: 1; }
}

